'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var MAX_UINT16 = require( '@stdlib/constants/uint16/max' );
var pkg = require( './../package.json' ).name;
var Float16 = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var y;
	var x;
	var i;
	b.tic();

	x = discreteUniform( 100, 0.0, MAX_UINT16 );

	for ( i = 0; i < b.iterations; i++ ) {
		y = new Float16( x[ i%x.length ] );
		if ( isnan( y ) ) {
			b.fail( 'should not return NaN' );
		}
	}
	b.toc();
	if ( !( y instanceof Float16 ) ) {
		b.fail( 'should return a complex number' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+'::get:value', function benchmark( b ) {
	var v;
	var x;
	var y;
	var i;

	x = discreteUniform( 100, 0.0, MAX_UINT16 );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		y = new Float16( x[ i%x.length ] );
		v = y.value;
		if ( isnan( v ) ) {
			b.fail( 'should not return NaN' );
		}
	}
	b.toc();
	if ( isnan( v ) ) {
		b.fail( 'should not return NaN' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+':toString', function benchmark( b ) {
	var o;
	var x;
	var y;
	var i;

	x = discreteUniform( 100, 0.0, MAX_UINT16 );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		y = new Float16( x[ i%x.length ] );
		o = y.toString();
		if ( typeof o !== 'string' ) {
			b.fail( 'should return a string' );
		}
	}
	b.toc();
	if ( typeof o !== 'string' ) {
		b.fail( 'should return a string' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( pkg+':toJSON', function benchmark( b ) {
	var o;
	var x;
	var y;
	var i;

	x = discreteUniform( 100, 0.0, MAX_UINT16 );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		y = new Float16( x[ i%x.length ] );
		o = y.toJSON();
		if ( typeof o !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( typeof o !== 'object' ) {
		b.fail( 'should return an object' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
